//! Cargo-driven `gdi32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is gdi32-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMain@12", Some(0x7c060000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMain", Some(0x7ffb3000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMain", Some(0x7ffb3000000u64)),
        o => panic!("gdi32-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:c:win32ksys", "engine:c:dxguid", "engine:atan2_rust", "engine:pseh", "body", "import:user32", "import:advapi32", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:crate:winegdi-rust::TRUE"],
        "x86_64" => &["engine:wine", "engine:c:win32ksys", "engine:c:dxguid", "engine:atan2_rust", "engine:pseh", "body", "import:user32", "import:advapi32", "import:kernel32", "import:ntdll", "engine:crate:winegdi-rust::TRUE"],
        "aarch64" => &["engine:wine", "engine:c:win32ksys", "engine:c:dxguid", "engine:atan2_rust", "engine:pseh", "body", "import:user32", "import:advapi32", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:crate:winegdi-rust::TRUE"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/win32ss/gdi/gdi32",
        "win32ss/gdi/gdi32",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "win32ss/gdi/gdi32/include",
        "win32ss/include",
        "sdk/lib/pseh/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["LANGPACK", "UNICODE", "WINVER=0x502", "_UNICODE", "_WIN32_WINNT=0x502"];

    Linker::new(target_json)
        .rust_staticlib("gdi32-rust")
        .rc("win32ss/gdi/gdi32/gdi32.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
